"use client"

import type { ReactNode } from "react"
import { GripVertical, Pencil, Trash2 } from "lucide-react"
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar"
import { Badge, type BadgeColor, type BadgeStyle } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import { Checkbox } from "@/components/ui/checkbox"
import { IconButton } from "@/components/ui/icon-button"
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group"
import { Rating } from "@/components/wunderui/rating"
import { Switch } from "@/components/ui/switch"
import { Popover, PopoverTrigger, PopoverContent } from "@/components/ui/popover"
import {
  NativeSelect,
  NativeSelectTrigger,
  NativeSelectValue,
  NativeSelectContent,
  NativeSelectItem,
} from "@/components/ui/native-select"
import { cn } from "@/lib/utils"

/**
 * The cell types of the Figma "Table Item" set. A data grid is mostly the same
 * handful of shapes repeated — a name over an email, a figure with its delta,
 * a control — so they live here as named pieces rather than being rebuilt in
 * every table.
 *
 * Two column heights recur: a single line of text sits in a 36 px row, a
 * two-line cell (user, company, product, address) in a 54 px one.
 */

const CELL_COLOR_SWATCHES = ["#12AFF0", "#A584F3", "#F3654A", "#FACA4A", "#1AD598", "#EC4899"]

/** Plain cell text. */
function TextCell({ children, className }: { children: ReactNode; className?: string }) {
  return <span className={cn("text-sm text-text-secondary", className)}>{children}</span>
}

/** Column header label — the only uppercase-weight cell in the set. */
function HeadingCell({ children, className }: { children: ReactNode; className?: string }) {
  return <span className={cn("text-xs font-semibold text-muted-foreground", className)}>{children}</span>
}

/** Name over email, with an avatar or a generic person glyph. */
function UserCell({
  name,
  email,
  avatarSrc,
  initials,
  avatarSize = "sm",
}: {
  name: string
  email?: string
  avatarSrc?: string
  initials?: string
  /** Avatar size; use "default" (36 px) when the cell shows name and email on two lines. */
  avatarSize?: "sm" | "xs" | "default" | "lg"
}) {
  return (
    <div className="flex items-center gap-3">
      <Avatar size={avatarSize}>
        {avatarSrc && <AvatarImage src={avatarSrc} alt="" />}
        <AvatarFallback>{initials ?? name.slice(0, 2).toUpperCase()}</AvatarFallback>
      </Avatar>
      <div className="flex flex-col">
        <span className="text-sm font-medium text-foreground">{name}</span>
        {email && <span className="text-xs text-muted-foreground">{email}</span>}
      </div>
    </div>
  )
}

/** Same shape as UserCell, but always a real avatar image or initials. */
function UserAvatarCell(props: Parameters<typeof UserCell>[0]) {
  return <UserCell {...props} />
}

function BadgeCell({
  label,
  color = "blue",
  badgeStyle = "light_border",
}: {
  label: string
  color?: BadgeColor
  badgeStyle?: BadgeStyle
}) {
  return (
    <Badge color={color} badgeStyle={badgeStyle}>
      {label}
    </Badge>
  )
}

function CurrencyCell({ value, currency = "$" }: { value: number; currency?: string }) {
  return (
    <span className="text-sm font-semibold text-muted-foreground">
      {currency}
      {value.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
    </span>
  )
}

/** A figure with its change — the delta is green when it is good news. */
function PerformanceCell({
  value,
  delta,
  good = true,
}: {
  value: string
  delta?: string
  good?: boolean
}) {
  return (
    <div className="flex items-baseline gap-2">
      <span className="text-sm font-semibold text-foreground">{value}</span>
      {delta && (
        <span className={cn("text-xs font-medium", good ? "text-text-success" : "text-text-error")}>{delta}</span>
      )}
    </div>
  )
}

/** Logo square, company name, domain. */
function CompanyCell({ name, domain, logoSrc }: { name: string; domain?: string; logoSrc?: string }) {
  return (
    <div className="flex items-center gap-3">
      <span className="size-8 shrink-0 overflow-hidden rounded-md bg-muted">
        {logoSrc && <img src={logoSrc} alt="" className="size-full object-cover" />}
      </span>
      <div className="flex flex-col">
        <span className="text-sm font-medium text-text-tertiary">{name}</span>
        {domain && <span className="text-xs text-muted-foreground">{domain}</span>}
      </div>
    </div>
  )
}

/** Thumbnail, product name, SKU. */
function ProductCell({ name, sku, imageSrc }: { name: string; sku?: string; imageSrc?: string }) {
  return (
    <div className="flex items-center gap-3">
      <span className="size-8 shrink-0 overflow-hidden rounded-md bg-muted">
        {imageSrc && <img src={imageSrc} alt="" className="size-full object-cover" />}
      </span>
      <div className="flex flex-col">
        <span className="text-sm font-medium text-foreground">{name}</span>
        {sku && <span className="text-xs text-muted-foreground">{sku}</span>}
      </div>
    </div>
  )
}

/** Street over city — two lines, no leading element. */
function AddressCell({ street, city }: { street: string; city?: string }) {
  return (
    <div className="flex flex-col">
      <span className="text-sm text-foreground">{street}</span>
      {city && <span className="text-xs text-muted-foreground">{city}</span>}
    </div>
  )
}

/** An icon beside a label. */
function IconTextCell({ icon, children }: { icon: ReactNode; children: ReactNode }) {
  return (
    <div className="flex items-center gap-3">
      <span className="flex shrink-0 items-center text-foreground [&_svg]:size-5">{icon}</span>
      <span className="text-sm text-foreground">{children}</span>
    </div>
  )
}

/** A small framed icon button beside a label. */
function IconButtonTextCell({
  icon,
  children,
  onClick,
  label,
}: {
  icon: ReactNode
  children: ReactNode
  onClick?: () => void
  label?: string
}) {
  return (
    <div className="flex items-center gap-3">
      <IconButton variant="plain" size="sm" aria-label={label ?? "Action"} onClick={onClick}>
        {icon}
      </IconButton>
      <span className="text-sm text-foreground">{children}</span>
    </div>
  )
}

/** A row of bare icon actions — edit, delete, view and the like. */
function ActionIconsCell({
  actions,
}: {
  actions: { icon: ReactNode; label: string; onClick?: () => void }[]
}) {
  return (
    <div className="flex items-center gap-4">
      {actions.map((action) => (
        <button
          key={action.label}
          type="button"
          aria-label={action.label}
          onClick={action.onClick}
          className="text-foreground transition-colors duration-fast ease-move hover:text-text-link [&_svg]:size-4"
        >
          {action.icon}
        </button>
      ))}
    </div>
  )
}

/** The filled call-to-action a row can carry. */
function CTAButtonCell({ children, onClick }: { children: ReactNode; onClick?: () => void }) {
  return (
    <Button variant="primary" size="sm" onClick={onClick}>
      {children}
    </Button>
  )
}

/** The quieter sibling of CTAButtonCell. */
function ButtonCell({ children, onClick }: { children: ReactNode; onClick?: () => void }) {
  return (
    <Button variant="plain" size="sm" onClick={onClick}>
      {children}
    </Button>
  )
}

/** Drag handle in front of the row label. */
function DragItemCell({ children }: { children: ReactNode }) {
  return (
    <div className="flex items-center gap-3">
      <GripVertical className="size-4 shrink-0 cursor-grab text-text-tertiary" />
      <span className="text-sm text-foreground">{children}</span>
    </div>
  )
}

function CheckItemCell({
  children,
  checked,
  onCheckedChange,
}: {
  children?: ReactNode
  checked?: boolean
  onCheckedChange?: (checked: boolean) => void
}) {
  return (
    <label className="flex items-center gap-3">
      <Checkbox checked={checked} onCheckedChange={onCheckedChange} />
      {children && <span className="text-sm text-foreground">{children}</span>}
    </label>
  )
}

function RadioItemCell({
  children,
  value,
  selected,
  onSelect,
}: {
  children?: ReactNode
  value: string
  selected?: string
  onSelect?: (value: string) => void
}) {
  return (
    <RadioGroup value={selected} onValueChange={(v) => onSelect?.(String(v))}>
      <label className="flex items-center gap-3">
        <RadioGroupItem value={value} />
        {children && <span className="text-sm text-foreground">{children}</span>}
      </label>
    </RadioGroup>
  )
}

function SwitchItemCell({
  children,
  checked,
  onCheckedChange,
}: {
  children?: ReactNode
  checked?: boolean
  onCheckedChange?: (checked: boolean) => void
}) {
  return (
    <label className="flex items-center gap-3">
      <Switch checked={checked} onCheckedChange={onCheckedChange} />
      {children && <span className="text-sm text-foreground">{children}</span>}
    </label>
  )
}

function ProgressCell({ value }: { value: number }) {
  return (
    <div className="flex items-center gap-2">
      <div className="h-1.5 w-20 overflow-hidden rounded-full bg-muted">
        <div className="h-full rounded-full bg-primary" style={{ width: `${Math.min(100, Math.max(0, value))}%` }} />
      </div>
      <span className="text-xs font-medium text-muted-foreground">{value}%</span>
    </div>
  )
}

/** A dismissible label — the Figma "Tag" cell is a badge with a cross. */
function TagCell({
  label,
  color = "indigo",
  onRemove,
}: {
  label: string
  color?: BadgeColor
  onRemove?: () => void
}) {
  return (
    <Badge color={color} badgeStyle="light" shape="pill">
      {label}
      {onRemove && (
        <button type="button" aria-label={`Remove ${label}`} onClick={onRemove} className="-mr-0.5 ml-0.5">
          <svg viewBox="0 0 12 12" className="size-3" aria-hidden>
            <path d="M3 3l6 6M9 3l-6 6" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" />
          </svg>
        </button>
      )}
    </Badge>
  )
}

/** Stars with the value beside them. */
function RatingCell({ value, max = 5 }: { value: number; max?: number }) {
  return <Rating value={value} max={max} label="right" readOnly />
}

function ActionItemsCell({ actions }: { actions: { label: string; onClick?: () => void; muted?: boolean }[] }) {
  return (
    <div className="flex items-center gap-4">
      {actions.map((a) => (
        <button
          key={a.label}
          onClick={a.onClick}
          className={cn("text-[13px] font-medium", a.muted ? "text-muted-foreground" : "text-text-link")}
        >
          {a.label}
        </button>
      ))}
    </div>
  )
}

function CellSwitch({
  checked,
  onCheckedChange,
  "aria-label": ariaLabel = "Toggle",
}: {
  checked: boolean
  onCheckedChange: (checked: boolean) => void
  /** Name for screen readers — a cell has no visible label of its own. */
  "aria-label"?: string
}) {
  return <Switch aria-label={ariaLabel} checked={checked} onCheckedChange={onCheckedChange} />
}

function CellSlider({ value, max = 100 }: { value: number; max?: number }) {
  return (
    <div className="flex w-28 items-center gap-2">
      <div className="h-1 flex-1 overflow-hidden rounded-full bg-muted">
        <div
          className="h-full rounded-full bg-primary"
          style={{ width: `${Math.min(100, (value / max) * 100)}%` }}
        />
      </div>
      <span className="w-7 text-right text-xs text-text-tertiary">{value}</span>
    </div>
  )
}

function CellSelect({
  value,
  onValueChange,
  options,
  "aria-label": ariaLabel = "Choose a value",
}: {
  value: string
  onValueChange: (value: string) => void
  options: string[]
  /** Name for screen readers — a combobox is not named by its current value. */
  "aria-label"?: string
}) {
  return (
    <NativeSelect value={value} onValueChange={(v) => v && onValueChange(v)}>
      <NativeSelectTrigger aria-label={ariaLabel} className="h-8 w-32 px-2 text-xs">
        <NativeSelectValue />
      </NativeSelectTrigger>
      <NativeSelectContent>
        {options.map((option) => (
          <NativeSelectItem key={option} value={option}>
            {option}
          </NativeSelectItem>
        ))}
      </NativeSelectContent>
    </NativeSelect>
  )
}

function CellColorPicker({
  value,
  onValueChange,
}: {
  value: string
  onValueChange: (value: string) => void
}) {
  return (
    <Popover>
      <PopoverTrigger
        aria-label={`Colour ${value}. Choose a colour`}
        className="size-6 rounded-full ring-1 ring-border ring-offset-2 ring-offset-card outline-none focus-visible:ring-1 focus-visible:ring-ring"
        style={{ backgroundColor: value }}
      />
      <PopoverContent className="w-auto p-2">
        <div className="grid grid-cols-6 gap-1.5">
          {CELL_COLOR_SWATCHES.map((swatch) => (
            <button
              key={swatch}
              type="button"
              aria-label={swatch}
              aria-pressed={value === swatch}
              onClick={() => onValueChange(swatch)}
              className={cn(
                "size-6 rounded-full transition-transform hover:scale-110",
                value === swatch && "ring-2 ring-foreground ring-offset-2 ring-offset-popover"
              )}
              style={{ backgroundColor: swatch }}
            />
          ))}
        </div>
      </PopoverContent>
    </Popover>
  )
}

/** The default icon set for ActionIconsCell — edit, delete, view. */
const TABLE_ACTION_ICONS = {
  edit: <Pencil />,
  delete: <Trash2 />,
} as const

export {
  TextCell,
  HeadingCell,
  UserCell,
  UserAvatarCell,
  BadgeCell,
  CurrencyCell,
  PerformanceCell,
  CompanyCell,
  ProductCell,
  AddressCell,
  IconTextCell,
  IconButtonTextCell,
  ActionIconsCell,
  CTAButtonCell,
  ButtonCell,
  DragItemCell,
  CheckItemCell,
  RadioItemCell,
  SwitchItemCell,
  ProgressCell,
  TagCell,
  RatingCell,
  ActionItemsCell,
  CellSwitch,
  CellSlider,
  CellSelect,
  CellColorPicker,
  TABLE_ACTION_ICONS,
}

"use client"

import * as React from "react"
import { Select as SelectPrimitive } from "@base-ui/react/select"
import { Check, ChevronDown } from "lucide-react"
import { cn } from "cn"
import { collectSelectItems } from "@/lib/select-items"

function NativeSelect({ items, children, ...props }: SelectPrimitive.Root.Props<string>) {
  // Derive the value → label map from the items in `children` unless given,
  // so the trigger shows "Germany" for value "de" right away.
  const derived = React.useMemo(() => (items ? undefined : collectSelectItems(children)), [items, children])
  return (
    <SelectPrimitive.Root data-slot="native-select" items={items ?? (derived && derived.length > 0 ? derived : undefined)} {...props}>
      {children}
    </SelectPrimitive.Root>
  )
}

function NativeSelectTrigger({ className, children, ...props }: SelectPrimitive.Trigger.Props) {
  return (
    <SelectPrimitive.Trigger
      data-slot="native-select-trigger"
      className={cn(
        "flex h-11 w-full items-center justify-between gap-2 rounded-md border border-input bg-transparent px-3 text-sm text-foreground outline-none focus-visible:border-ring data-disabled:pointer-events-none data-disabled:opacity-50",
        className
      )}
      {...props}
    >
      {children}
      <SelectPrimitive.Icon>
        <ChevronDown className="size-4 text-text-tertiary" />
      </SelectPrimitive.Icon>
    </SelectPrimitive.Trigger>
  )
}

function NativeSelectValue({ ...props }: SelectPrimitive.Value.Props) {
  return <SelectPrimitive.Value data-slot="native-select-value" {...props} />
}

function NativeSelectContent({ className, children, ...props }: SelectPrimitive.Popup.Props) {
  return (
    <SelectPrimitive.Portal>
      <SelectPrimitive.Positioner className="isolate z-50 outline-none" sideOffset={4}>
        <SelectPrimitive.Popup
          data-slot="native-select-content"
          className={cn(
            "z-50 max-h-(--available-height) w-(--anchor-width) min-w-32 overflow-y-auto rounded-lg bg-popover p-1 text-popover-foreground shadow-md ring-1 ring-foreground/10 outline-none",
            className
          )}
          {...props}
        >
          {children}
        </SelectPrimitive.Popup>
      </SelectPrimitive.Positioner>
    </SelectPrimitive.Portal>
  )
}

function NativeSelectItem({ className, children, ...props }: SelectPrimitive.Item.Props) {
  return (
    <SelectPrimitive.Item
      data-slot="native-select-item"
      className={cn(
        "relative flex cursor-default items-center rounded-md py-1.5 pr-8 pl-2 text-sm outline-hidden select-none data-highlighted:bg-accent data-highlighted:text-accent-foreground",
        className
      )}
      {...props}
    >
      <SelectPrimitive.ItemText>{children}</SelectPrimitive.ItemText>
      <span className="absolute right-2 flex items-center justify-center">
        <SelectPrimitive.ItemIndicator>
          <Check className="size-4" />
        </SelectPrimitive.ItemIndicator>
      </span>
    </SelectPrimitive.Item>
  )
}

export {
  NativeSelect,
  NativeSelectTrigger,
  NativeSelectValue,
  NativeSelectContent,
  NativeSelectItem,
}

import * as React from "react"

/**
 * Collects `{ value, label }` pairs from `<…Item value>label</…Item>` elements
 * anywhere in a Select's children, so `<Select.Value>` can show the label
 * before the popup has ever opened (Base UI otherwise renders the raw value).
 */
function collectSelectItems(children: React.ReactNode): { value: string; label: React.ReactNode }[] {
  const items: { value: string; label: React.ReactNode }[] = []
  const walk = (node: React.ReactNode) => {
    React.Children.forEach(node, (child) => {
      if (!React.isValidElement(child)) return
      const props = child.props as { value?: unknown; children?: React.ReactNode }
      if (typeof props.value === "string" && props.children !== undefined && typeof child.type !== "string") {
        items.push({ value: props.value, label: props.children })
      }
      if (props.children) walk(props.children)
    })
  }
  walk(children)
  return items
}

export { collectSelectItems }

"use client"

import * as React from "react"
import { Popover as PopoverPrimitive } from "@base-ui/react/popover"
import { cn } from "cn"

function Popover({ ...props }: PopoverPrimitive.Root.Props) {
  return <PopoverPrimitive.Root data-slot="popover" {...props} />
}

function PopoverTrigger({ ...props }: PopoverPrimitive.Trigger.Props) {
  return <PopoverPrimitive.Trigger data-slot="popover-trigger" {...props} />
}

function PopoverContent({
  className,
  sideOffset = 8,
  side,
  align,
  anchor,
  ...props
}: PopoverPrimitive.Popup.Props & Pick<PopoverPrimitive.Positioner.Props, "sideOffset" | "side" | "align" | "anchor">) {
  return (
    <PopoverPrimitive.Portal>
      <PopoverPrimitive.Positioner className="isolate z-50 outline-none" sideOffset={sideOffset} side={side} align={align} anchor={anchor}>
        <PopoverPrimitive.Popup
          data-slot="popover-content"
          className={cn(
            "z-50 rounded-lg border border-border bg-popover [--surface:var(--popover)] p-3 text-popover-foreground shadow-lg outline-none",
            "data-open:animate-in data-open:fade-in-0 data-open:zoom-in-95 data-open:duration-base data-open:ease-overshoot data-closed:animate-out data-closed:fade-out-0 data-closed:zoom-out-99 data-closed:duration-fast data-closed:ease-exit",
            className
          )}
          {...props}
        />
      </PopoverPrimitive.Positioner>
    </PopoverPrimitive.Portal>
  )
}

/** Closes the popover it sits in — render it as an icon button for an ×, or around Cancel/Apply. */
function PopoverClose({ ...props }: PopoverPrimitive.Close.Props) {
  return <PopoverPrimitive.Close data-slot="popover-close" {...props} />
}

export { Popover, PopoverTrigger, PopoverContent, PopoverClose }

"use client"

import * as React from "react"
import { Switch as SwitchPrimitive } from "@base-ui/react/switch"
import { cn } from "cn"

function Switch({
  className,
  size = "default",
  ...props
}: SwitchPrimitive.Root.Props & {
  size?: "sm" | "default"
}) {
  // The bounce keyframes are skipped on the render that mounts the switch —
  // without this, every switch on the page would play its "on" bounce once
  // at load just because the attribute selector newly matches. Deriving this
  // from mount (not a click handler) means it can't land a render behind the
  // actual checked-state change, which would otherwise let a stray "on"
  // bounce play for a split second before the real "off" toggle catches up.
  const isInitialRender = React.useRef(true)
  React.useEffect(() => {
    isInitialRender.current = false
  }, [])

  return (
    <SwitchPrimitive.Root
      data-slot="switch"
      data-size={size}
      data-init={!isInitialRender.current || undefined}
      className={cn(
        "peer group/switch relative inline-flex shrink-0 items-center rounded-full border border-transparent transition duration-fast ease-entrance outline-none group-has-[:focus-visible]/field-label:border-transparent group-has-[:focus-visible]/field-label:ring-0 after:absolute after:-inset-x-3 after:-inset-y-2 focus-visible:border-ring aria-invalid:border-destructive aria-invalid:ring-3 aria-invalid:ring-destructive/20 data-[size=default]:h-5 data-[size=default]:w-10 data-[size=default]:[--switch-travel:22px] data-[size=sm]:h-4 data-[size=sm]:w-8 data-[size=sm]:[--switch-travel:18px] dark:aria-invalid:border-destructive/50 dark:aria-invalid:ring-destructive/40 data-checked:bg-primary data-unchecked:bg-dark-400 data-disabled:cursor-not-allowed data-disabled:opacity-50",
        className
      )}
      {...props}
    >
      <SwitchPrimitive.Thumb
        data-slot="switch-thumb"
        className="pointer-events-none block rounded-full bg-background ring-0 transition-transform duration-fast ease-entrance group-data-[size=default]/switch:size-4 group-data-[size=sm]/switch:size-3 data-checked:translate-x-(--switch-travel) dark:data-checked:bg-primary-foreground group-data-[size=default]/switch:data-unchecked:translate-x-0 group-data-[size=sm]/switch:data-unchecked:translate-x-0 dark:data-unchecked:bg-foreground group-data-init/switch:data-checked:[animation:wunderui-switch-on_var(--duration-slow)_var(--ease-overshoot)_both] group-data-init/switch:data-unchecked:[animation:wunderui-switch-off_var(--duration-slow)_var(--ease-overshoot)_both]"
      />
    </SwitchPrimitive.Root>
  )
}

export { Switch }

"use client"

import * as React from "react"
import { Heart, Star } from "lucide-react"
import { cn } from "@/lib/utils"

type RatingType = "stars" | "hearts" | "emojis" | "scale"
type RatingLabel = "none" | "left" | "right" | "tooltip"

const EMOJIS = ["😍", "🙂", "😐", "🙁", "😡"]

/**
 * Rating — mirrors the Figma Rating set (Type × Value × Label).
 * - `stars` / `hearts`: fill `value` of `max` icons (yellow / pink).
 * - `emojis`: single-select reaction 1–5 (😍 🙂 😐 🙁 😡), 0 = none.
 * - `scale`: 0–10 NPS row, the selected number is filled.
 * `label` shows the value beside the rating or as a tooltip above it.
 */
function Rating({
  value,
  onValueChange,
  max,
  type = "stars",
  label = "none",
  readOnly = false,
  className,
}: {
  value: number
  onValueChange?: (value: number) => void
  max?: number
  type?: RatingType
  label?: RatingLabel
  readOnly?: boolean
  className?: string
}) {
  const [hover, setHover] = React.useState<number | null>(null)
  const display = hover ?? value
  const count = max ?? (type === "scale" ? 11 : 5)
  const text = type === "scale" || type === "emojis" ? String(value) : `${value.toFixed(1)}`

  const labelNode =
    label === "none" ? null : label === "tooltip" ? (
      <span className="pointer-events-none absolute -top-8 left-1/2 -translate-x-1/2 rounded-md border border-border bg-card px-2 py-1 text-xs font-medium text-foreground shadow-md">
        {text}
      </span>
    ) : (
      <span className="text-sm font-medium tabular-nums text-foreground">{text}</span>
    )

